// Author: MiYu. Play model sequences with source cameras and scene-specific sound labels.
#include "model_cinematic.h"
#include <cctype>
#include <algorithm>
#include <map>
namespace war3 {
namespace {
std::string mdxPath(std::string path){auto extension=fs::path(wide(path)).extension().wstring();if(extension==L".mdl" || extension==L".MDL")path.replace(path.size()-4,4,".mdx");else if(extension!=L".mdx" && extension!=L".MDX")throw std::runtime_error("Invalid model cinematic source");return path;}
}
ModelCinematic::ModelCinematic(Archives& archives,Images& images,Renderer& renderer,Log& log,const std::string& source,bool muted) : model_(archives,images,&renderer,mdxPath(source).c_str(),log),sound_(archives),renderer_(renderer) {
    auto count=model_.sequenceCount();if(!count || count!=model_.cameraCount() || count>4096)throw std::runtime_error("Model cinematic requires one camera for each sequence");SourceSettings config;config.load(archives,"UI\\MiscData.txt");auto section=utf8(fs::path(wide(source)).stem().wstring())+"Sounds";sound_.muted(muted);for(size_t i=0;i<count;++i){if(!model_.sequenceIndex(unsigned(i)))throw std::runtime_error("Missing cinematic sequence");auto duration=model_.sequenceDuration();if(!duration)throw std::runtime_error("Empty cinematic sequence");durations_.push_back(duration);labels_.push_back(config.value(section,"Scene"+std::to_string(i)));prepared_.push_back(labels_.back().empty()?nullptr:sound_.fromLabel(labels_.back(),false,false,false,0,0));}
    auto path=mdxPath(source);for(auto& c:path)c=c=='/'?'\\':char(std::tolower(static_cast<unsigned char>(c)));if(path=="doodads\\cinematic\\arthasillidanfight\\arthasillidanfight.mdx"){
        std::map<std::string,int> starts,ends;for(auto& event:model_.events()){if(!event.name.starts_with("MRFX") && !event.name.starts_with("MRDX"))continue;auto id=event.name.substr(4);if(id.size()!=4 || !std::all_of(id.begin(),id.end(),[](unsigned char c){return std::isdigit(c);}) || event.parent!=-1 || event.global!=-1 || event.animated || event.times.size()!=1)throw std::runtime_error("Unsupported model morph event");auto& list=event.name.starts_with("MRFX")?starts:ends;if(!list.emplace(id,event.times.front()).second)throw std::runtime_error("Duplicate model morph event");}if(starts.size()!=ends.size())throw std::runtime_error("Unpaired model morph events");std::map<std::string,Com<IDirect3DTexture9>> textures;for(auto [id,begin]:starts){auto end=ends.find(id);if(end==ends.end() || end->second<=begin)throw std::runtime_error("Invalid model morph interval");bool found=false;for(size_t i=0;i<count;++i){model_.sequenceIndex(unsigned(i));auto first=model_.sequenceStart();auto last=std::int64_t(first)+std::int64_t(durations_[i]);if(begin>=first && end->second<=last){auto file="Doodads\\Cinematic\\ArthasIllidanFight\\ArthasCape"+id+".mrf";morphs_.push_back({i,std::uint64_t(begin-first),std::uint64_t(end->second-first),std::make_unique<MorphMesh>(archives,images,renderer,file,textures)});found=true;break;}}if(!found)throw std::runtime_error("Model morph event outside sequence");}}
    start_=GetTickCount64();select(0);log.write("model_cinematic_scenes="+std::to_string(count)+" morphs="+std::to_string(morphs_.size()));
}
void ModelCinematic::select(size_t index){if(!model_.sequenceIndex(unsigned(index)) || !model_.cameraIndex(unsigned(index)))throw std::runtime_error("Missing model cinematic scene");scene_=index;if(prepared_[index]){if(playing_)sound_.stop(playing_,true,false);playing_=prepared_[index];sound_.start(playing_);}}
bool ModelCinematic::draw(float aspect){auto elapsed=GetTickCount64()-start_;while(elapsed-sceneStart_>=durations_[scene_]){sceneStart_+=durations_[scene_];if(scene_+1>=durations_.size())return false;select(scene_+1);}sound_.update();auto local=elapsed-sceneStart_;model_.draw(local,aspect,true,elapsed);for(auto& morph:morphs_)if(morph.scene==scene_ && local>=morph.begin && local<morph.end)morph.mesh->draw(renderer_,double(local-morph.begin)/1000.);return true;}
}
